scripts:
(() => {
  const plans = [
    { name: 'Bronze', sites: 1, disk: 30, price: 6, why: '1 website · 30GB NVMe · 1 vCPU' },
    { name: 'Silver', sites: 100, disk: 50, price: 10, why: 'Up to 100 websites · 50GB NVMe · 2 vCPU' },
    { name: 'Gold', sites: Infinity, disk: 100, price: 15, why: 'Unlimited websites · 100GB NVMe · 2 vCPU' },
  ];
  const $ = (id) => document.getElementById(id);
  const money = (n) => '$' + (Math.round(n * 100) / 100).toLocaleString('en-US', { minimumFractionDigits: n % 1 ? 2 : 0, maximumFractionDigits: 2 });
  const years = $('years');
  let last = '';
  const calc = () => {
    const sites = +$('sites').value, disk = +$('disk').value, yrs = +(years.dataset.value || 3);
    $('sites-out').textContent = sites >= 150 ? '150+' : sites;
    $('disk-out').textContent = disk + ' GB';
    const plan = plans.find((p) => sites <= p.sites && disk <= p.disk * 0.85) || plans[2];
    const intro = parseFloat($('intro').value);
    const first = Number.isFinite(intro) && intro > 0 ? intro : plan.price;
    const y1 = first * 12, rest = plan.price * 12 * (yrs - 1);
    $('plan-name').textContent = plan.name;
    $('plan-why').textContent = plan.why;
    $('r-renew').textContent = money(plan.price) + '/mo';
    $('r-y1').textContent = money(y1);
    $('r-rest-lbl').textContent = yrs === 1 ? 'Later years' : (yrs === 2 ? 'Year 2' : 'Years 2–3');
    $('r-rest').textContent = yrs === 1 ? '—' : money(rest);
    $('r-total').textContent = money(y1 + rest);
    $('plan-cta').textContent = `Check ${plan.name} on Verpex ↗`;
    document.querySelectorAll('#plan-cards .plan-card').forEach((c) => c.classList.toggle('is-pick', c.dataset.plan === plan.name));
    if (plan.name !== last) { window.fgBump?.($('plan-name')); last = plan.name; }
  };
  ['sites', 'disk', 'intro'].forEach((id) => $(id).addEventListener('input', calc));
  years.addEventListener('change', calc);
  calc();
})();
